<script setup lang="ts">
import { qtrc, useLanguage } from '../../../i18n'
import { ICON_CODES } from '../../../actions/uiactiondata'
import { styleDialogImage } from './images'
import type { NotationStyleLike } from './controls.vue'
const props=defineProps<{style:NotationStyleLike;goToTextStylePage?:(code:string)=>void}>()
useLanguage()
const tr=(s:string)=>qtrc('notation/editstyle/hammeronpulloff',s)
const toggle=(id:string)=>props.style.setValue(id,!props.style.value(id))
const shows=[['Half slur',0],['Symbol',1],['Both',2]] as const
const hands=[{show:'lhTappingShowItemsNormalStave',symbol:'lhTappingSymbolNormalStave',label:'Show on standard staves'},{show:'lhTappingShowItemsTab',symbol:'lhTappingSymbolTab',label:'Show on tablature staves'}]
</script>
<template>
<div class="sd-column" style="gap:12px">
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Visibility')}}</legend><div class="sd-column" style="gap:10px"><span class="sd-label">{{tr('Show ‘H’ and ‘P’ symbols on')}}</span><label v-for="[id,label] in [['hopoShowOnStandardStaves','Standard staves'],['hopoShowOnTabStaves','Tablature staves']]" :key="id" class="sd-toggle"><input type="checkbox" role="switch" :checked="style.value(id)===true" @change="toggle(id)"><span class="sd-toggle-track" aria-hidden="true"></span><span>{{tr(label)}}</span></label></div></fieldset>
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Case')}}</legend><div class="sd-column" style="gap:12px"><div class="sd-row" style="gap:8px"><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="[icon,label,value] in [[ICON_CODES.HP_UPPER_CASE,'Upper case',true],[ICON_CODES.HP_LOWER_CASE,'Lower case',false]] as const" :key="label" type="button" role="radio" class="sd-flat-radio" style="width:40px;height:30px;flex:none" :title="tr(label)" :aria-label="tr(label)" :aria-checked="style.value('hopoUpperCase')===value" @click="style.setValue('hopoUpperCase',value)"><span class="sd-icon">{{String.fromCodePoint(icon)}}</span></button></div><div class="sd-vseparator"></div><button type="button" class="sd-flat-button" @click="goToTextStylePage?.('hammer-ons-pull-offs-and-tapping')">{{tr('Edit text style')}}</button></div></div></fieldset>
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Alignment')}}</legend><div class="sd-column" style="gap:10px"><span class="sd-label">{{tr('Align ‘H’, ‘P’ and ‘T’ symbols in the same slur on')}}</span><label v-for="[id,label] in [['hopoAlignLettersStandardStaves','Standard staves'],['hopoAlignLettersTabStaves','Tablature staves']]" :key="id" class="sd-checkbox"><input type="checkbox" :checked="style.value(id)===true" @change="toggle(id)"><span>{{tr(label)}}</span></label></div></fieldset>
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Consecutive hammer-ons/pull-offs')}}</legend><div class="sd-column" style="gap:8px"><div class="sd-column" role="radiogroup" style="gap:8px"><label v-for="[label,value] in [['Show ‘H’ or ‘P’ between each pair of notes',true],['Show ‘H’ or ‘P’ once per group of ascending/descending notes',false]] as const" :key="label" class="sd-radio"><input type="radio" name="hopoShowAll" :checked="style.value('hopoShowAll')===value" @change="style.setValue('hopoShowAll',value)"><span>{{tr(label)}}</span></label></div><div><div class="sd-image" style="padding:8px"><img :src="styleDialogImage('hammerOnPullOffImages/'+(style.value('hopoShowAll')?'hopoShowAll':'hopoNotShowAll'))" alt="" style="height:180px"></div></div></div></fieldset>
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Left-hand tapping')}}</legend><div class="sd-column" style="gap:8px"><div v-for="hand in hands" :key="hand.show" class="sd-row" style="gap:24px"><div class="sd-column" style="gap:8px"><span class="sd-label">{{tr(hand.label)}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="[label,value] in shows" :key="value" type="button" role="radio" class="sd-flat-radio" style="height:30px" :aria-checked="style.value(hand.show)===value" @click="style.setValue(hand.show,value)">{{tr(label)}}</button></div></div><div class="sd-column" :class="{disabled:style.value(hand.show)===0}" style="gap:8px"><span class="sd-label">{{tr('Symbol')}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="[icon,value] in [[ICON_CODES.TAPPING_ENCIRCLED_T,1],[ICON_CODES.TAPPING_DOT,0]]" :key="value" type="button" role="radio" class="sd-flat-radio" style="width:40px;height:30px;flex:none" :aria-checked="style.value(hand.symbol)===value" @click="style.value(hand.show)!==0 && style.setValue(hand.symbol,value)"><span class="sd-icon">{{String.fromCodePoint(icon)}}</span></button></div></div></div><label class="sd-checkbox" :class="{disabled:style.value('lhTappingShowItemsTab')===1}"><input type="checkbox" :disabled="style.value('lhTappingShowItemsTab')===1" :checked="style.value('lhTappingSlurTopAndBottomNoteOnTab')===true" @change="toggle('lhTappingSlurTopAndBottomNoteOnTab')"><span>{{tr('Slur top and bottom notes in chords')}}</span></label></div></fieldset>
 <fieldset class="sd-groupbox" style="min-width:500px"><legend>{{tr('Right-hand tapping')}}</legend><div class="sd-column" style="gap:12px"><div v-for="[id,label] in [['rhTappingSymbolNormalStave','Symbol (standard staff)'],['rhTappingSymbolTab','Symbol (tablature staff)']]" :key="id" class="sd-column" style="gap:8px"><span class="sd-label">{{tr(label)}}</span><div class="sd-flat-radio-group" role="radiogroup" style="gap:4px"><button v-for="[icon,value] in [[ICON_CODES.TAPPING_PLUS,1],[ICON_CODES.TAPPING_T,0]]" :key="value" type="button" role="radio" class="sd-flat-radio" style="width:40px;height:30px;flex:none" :aria-checked="style.value(id)===value" @click="style.setValue(id,value)"><span class="sd-icon">{{String.fromCodePoint(icon)}}</span></button></div></div></div></fieldset>
</div>
</template>
